alter table public.note_folders add column if not exists shared_with_client boolean not null default false; do $$ begin if not exists ( select 1 from pg_constraint where conrelid = to_regclass('public.note_folders') and conname = 'note_folders_shared_needs_client' ) then alter table public.note_folders add constraint note_folders_shared_needs_client check (not shared_with_client or client_id is not null); end if; end $$; create or replace function public.note_folder_shared_with_me(target_folder_id uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists ( select 1 from public.note_folders f left join public.note_folders p on p.id = f.parent_id where f.id = target_folder_id and public.current_client_id() is not null and ( (f.shared_with_client and f.client_id = public.current_client_id()) or (p.shared_with_client and p.client_id = public.current_client_id()) ) ); $$; grant execute on function public.note_folder_shared_with_me(uuid) to authenticated; drop policy if exists "note_folders: client reads shared" on public.note_folders; create policy "note_folders: client reads shared" on public.note_folders for select using ( public.current_role() = 'client' and public.note_folder_shared_with_me(id) ); drop policy if exists "notes: client reads shared" on public.notes; create policy "notes: client reads shared" on public.notes for select using ( public.current_role() = 'client' and folder_id is not null and public.note_folder_shared_with_me(folder_id) ); drop policy if exists "note_checklist_items: client reads shared" on public.note_checklist_items; create policy "note_checklist_items: client reads shared" on public.note_checklist_items for select using ( public.current_role() = 'client' and exists ( select 1 from public.notes n where n.id = note_id and n.folder_id is not null and public.note_folder_shared_with_me(n.folder_id) ) );
